using System.Numerics;
using System.Security.Cryptography;
using MathUtils;

namespace AsymmetricCryptography;

/// <summary>
/// Implementation of ElGamal.
/// </summary>
public class ElGamal {

    #region Record types

    /// <summary>
    /// ElGamal group parameters.
    /// </summary>
    /// <param name="P">The modulus for group operations.</param>
    /// <param name="Q">The order of the prime subgroup generated by <paramref name="G"/>.</param>
    /// <param name="G">The generator for the group.</param>
    public sealed record Parameters(BigInteger P, BigInteger Q, BigInteger G);

    /// <summary>
    /// An ElGamal public key.
    /// </summary>
    /// <param name="H">The public value.</param>
    /// <param name="Parameters">The group parameters.</param>
    public sealed record PublicKey(BigInteger H, Parameters Parameters);

    /// <summary>
    /// An ElGamal private key.
    /// </summary>
    /// <param name="X">The private exponent.</param>
    /// <param name="Parameters">The group parameters.</param>
    public sealed record PrivateKey(BigInteger X, Parameters Parameters);

    /// <summary>
    /// An ElGamal key pair.
    /// </summary>
    /// <param name="PublicKey">The public key.</param>
    /// <param name="PrivateKey">The private key.</param>
    public sealed record KeyPair(PublicKey PublicKey, PrivateKey PrivateKey);

    #endregion

    #region Configuration

    /// <summary>
    /// The smallest modulus size, in bits, this implementation will generate or accept.
    /// </summary>
    public const int MinimumBitLength = 64;

    #endregion

    #region Members

    private readonly Parameters _Parameters;
    private readonly PublicKey _PublicKey;
    private readonly PrivateKey? _PrivateKey;
    private readonly KeyPair? _KeyPair;

    /// <summary>Number of bytes needed to hold the modulus.</summary>
    public int ModulusByteCount => (int)((_Parameters.P.GetBitLength() + 7) / 8);

    #endregion

    #region Key retrieval

    /// <summary>Returns the parameters used by this instance.</summary>
    public Parameters GetParameters() => _Parameters;

    /// <summary>Returns the public key held by this instance.</summary>
    public PublicKey GetPublicKey() => _PublicKey;

    /// <summary>Returns the private key held by this instance.</summary>
    /// <exception cref="InvalidOperationException">
    /// Thrown when this instance was constructed from a public key only.
    /// </exception>
    public PrivateKey GetPrivateKey() =>
        _PrivateKey ?? throw new InvalidOperationException("No private key is held.");

    /// <summary>Returns the public/private key pair.</summary>
    /// <exception cref="InvalidOperationException">
    /// Thrown when this instance was constructed from a public key only.
    /// </exception>
    public KeyPair GetKeyPair() =>
        _KeyPair ?? throw new InvalidOperationException("No private key is held.");

    #endregion

    #region Constructors

    /// <summary>
    /// Create an ElGamal instance. Generates parameters and key pair.
    /// </summary>
    /// <param name="bitLength">Modulus size in bits.</param>
    /// <exception cref="ArgumentOutOfRangeException"><paramref name="bitLength"/> is below <see cref="MinimumBitLength"/>.</exception>
    /// <exception cref="ArgumentException"><paramref name="bitLength"/> is odd.</exception>
    public ElGamal(int bitLength) : this(GenerateParameters(bitLength)) { }

    /// <summary>
    /// Create an ElGamal instance. Generates a key pair with the given parameters.
    /// </summary>
    /// <param name="parameters">Group parameters to use.</param>
    /// <exception cref="ArgumentException"><paramref name="parameters"/> is malformed.</exception>
    public ElGamal(Parameters parameters) : this(GenerateKeyPair(parameters)) { }

    /// <summary>
    /// Wraps an existing public key. The resulting instance can encrypt and verify but not
    /// decrypt or sign.
    /// </summary>
    /// <param name="publicKey">The public key to use.</param>
    /// <exception cref="ArgumentOutOfRangeException">
    /// The modulus is not a positive odd integer of at least <see cref="MinimumBitLength"/> bits,
    /// the group parameters are malformed, or the public value is not a valid subgroup element.
    /// </exception>
    public ElGamal(PublicKey publicKey) {
        if (publicKey is null || publicKey.Parameters is null)
            throw new ArgumentNullException(nameof(publicKey));

        Parameters prm = publicKey.Parameters;
        ValidateParameters(prm, nameof(publicKey));

        BigInteger h = publicKey.H;
        if (h < 2 || h > prm.P - 2 || BigInteger.ModPow(h, prm.Q, prm.P) != 1)
            throw new ArgumentOutOfRangeException(nameof(publicKey),
                "Public value H is not a valid element of the subgroup.");

        _Parameters = prm;
        _PublicKey = publicKey;
        _PrivateKey = null;
        _KeyPair = null;
    }

    /// <summary>
    /// Wraps an existing key pair.
    /// </summary>
    /// <param name="keyPair">The key pair to adopt.</param>
    /// <exception cref="ArgumentOutOfRangeException">The private exponent is outside <c>[1, Q)</c>, or the public half is malformed.</exception>
    /// <exception cref="ArgumentException">The private key does not match the public key.</exception>
    public ElGamal(KeyPair keyPair) : this(RequirePublic(keyPair)) {
        PrivateKey priv = keyPair.PrivateKey ?? throw new ArgumentNullException(nameof(keyPair));
        Parameters p = _Parameters;

        if (priv.X < 1 || priv.X >= p.Q)
            throw new ArgumentOutOfRangeException(nameof(keyPair), "Private exponent is out of range.");

        if (priv.Parameters != keyPair.PublicKey.Parameters)
            throw new ArgumentException("Private and public key parameters do not match.", nameof(keyPair));

        if (BigInteger.ModPow(p.G, priv.X, p.P) != keyPair.PublicKey.H)
            throw new ArgumentException("Private key does not match the public key.", nameof(keyPair));

        _PrivateKey = priv;
        _KeyPair = keyPair;
    }

    private static PublicKey RequirePublic(KeyPair keyPair) {
        ArgumentNullException.ThrowIfNull(keyPair);
        return keyPair.PublicKey ?? throw new ArgumentNullException(nameof(keyPair));
    }

    private static void ValidateParameters(Parameters prm, string paramName) {
        BigInteger p = prm.P, q = prm.Q, g = prm.G;

        if (p.Sign <= 0 || p.IsEven || p.GetBitLength() < MinimumBitLength)
            throw new ArgumentOutOfRangeException(paramName,
                "Modulus must be a positive odd integer of at least the minimum bit length.");

        if (q < 2 || q >= p || (p - 1) % q != 0)
            throw new ArgumentOutOfRangeException(paramName,
                "Q must be in [2, P) and divide P - 1.");

        if (g < 2 || g >= p || BigInteger.ModPow(g, q, p) != 1)
            throw new ArgumentOutOfRangeException(paramName,
                "G must be in [2, P) and have order dividing Q.");
    }

    private static Parameters GenerateParameters(int bitLength) {
        if (bitLength < MinimumBitLength)
            throw new ArgumentOutOfRangeException(nameof(bitLength), "Bit length is below the minimum.");
        if (bitLength % 2 != 0)
            throw new ArgumentException("Bit length must be even.", nameof(bitLength));

        //This same logic was just ripped from my Diffie Hellman
        BigInteger q, p;
        do {
            q = GetRandomPrime(bitLength - 1);
            p = 2 * q + 1;
        } while (!IsProbablePrime(p));

        BigInteger g;
        do {
            g = BigInteger.ModPow(RandomBigInteger(2, p - 1), 2, p);
        } while (g == 1);

        return new Parameters(p, q, g);
    }

    private static KeyPair GenerateKeyPair(Parameters parameters) {
      if(parameters == null){
        throw new ArgumentException("Null parameters in GenerateKeyPair");
      }
        ValidateParameters(parameters, nameof(parameters));

        BigInteger x = RandomBigInteger(1, parameters.Q);   
        BigInteger h = BigInteger.ModPow(parameters.G, x, parameters.P);
        return new KeyPair(new PublicKey(h, parameters), new PrivateKey(x, parameters));
    }

    #endregion


    //Bunch of helper function
    //
    //    #region Helpers
    //
    //
    private byte[] ToFixedBytes(BigInteger v) {
        byte[] raw = v.ToByteArray(isUnsigned: true, isBigEndian: true);
        byte[] result = new byte[ModulusByteCount];
        raw.CopyTo(result, ModulusByteCount - raw.Length);
        return result;
    }

    private static BigInteger FromBytes(ReadOnlySpan<byte> bytes) =>
        new(bytes, isUnsigned: true, isBigEndian: true);

    private static BigInteger HashToExponent(ReadOnlySpan<byte> data, HashAlgorithmName hash, BigInteger q) {
        using IncrementalHash h = IncrementalHash.CreateHash(hash);
        h.AppendData(data);
        byte[] digest = h.GetHashAndReset();
        return FromBytes(digest) % q;
    }

    // ---- OAEP adapter -------------------------------------------------------------
    // These two methods are the ONLY place that touches OAEPEncoder. If your encoder's
    // method names or signatures differ, change them here and nowhere else.
    // Encode must return a block of exactly 'blockLength' bytes (leading byte 0x00).

    private static byte[] OaepEncode(OAEPEncoder encoder, ReadOnlySpan<byte> plaintext, int blockLength) =>
        encoder.Encode(plaintext, blockLength);

    private static byte[] OaepDecode(OAEPEncoder encoder, byte[] block) =>
        encoder.Decode(block);

    #region Encryption operations

    /// <summary>
    /// Encrypts a message using OAEP with SHA-256 and an empty label.
    /// </summary>
    /// <param name="plaintext">The message to encrypt.</param>
    /// <returns>A ciphertext 2*<see cref="ModulusByteCount"/> bytes long (c1 || c2).</returns>
    /// <exception cref="ArgumentException">The plaintext is too long for the modulus.</exception>
    public byte[] Encrypt(ReadOnlySpan<byte> plaintext) => Encrypt(plaintext, new OAEPEncoder(HashAlgorithmName.SHA256));

    /// <summary>
    /// Encrypts a message using a caller-supplied OAEP encoder.
    /// </summary>
    /// <param name="plaintext">The message to encrypt.</param>
    /// <param name="encoder">The OAEP encoder supplying the hash, MGF1 hash, and label.</param>
    /// <returns>A ciphertext 2*<see cref="ModulusByteCount"/> bytes long (c1 || c2).</returns>
    /// <exception cref="ArgumentException">The plaintext exceeds the encoder's capacity for this modulus.</exception>
    public byte[] Encrypt(ReadOnlySpan<byte> plaintext, OAEPEncoder encoder) {
        ArgumentNullException.ThrowIfNull(encoder);

        BigInteger p = _Parameters.P, q = _Parameters.Q, g = _Parameters.G;

        byte[] block;
        try {
            block = OaepEncode(encoder, plaintext, ModulusByteCount);
        } catch (Exception ex) when (ex is not ArgumentException) {
            throw new ArgumentException("The plaintext is too long for this modulus.", nameof(plaintext), ex);
        }

        BigInteger m = FromBytes(block);
        if (m.IsZero || m >= p)
            throw new ArgumentException("Encoded message is not a valid group element.", nameof(plaintext));

        BigInteger k = RandomBigInteger(1, q);
        BigInteger c1 = BigInteger.ModPow(g, k, p);
        BigInteger c2 = m * BigInteger.ModPow(_PublicKey.H, k, p) % p;

        byte[] ct = new byte[2 * ModulusByteCount];
        ToFixedBytes(c1).CopyTo(ct, 0);
        ToFixedBytes(c2).CopyTo(ct, ModulusByteCount);
        return ct;
    }

    /// <summary>
    /// Decrypts a ciphertext produced with OAEP using SHA-256 and an empty label.
    /// </summary>
    /// <param name="ciphertext">The ciphertext, which must be 2*<see cref="ModulusByteCount"/> bytes.</param>
    /// <returns>The recovered plaintext.</returns>
    /// <exception cref="InvalidOperationException">No private key is held.</exception>
    /// <exception cref="ArgumentException">The ciphertext is the wrong length, too large, or fails OAEP checks.</exception>
    public byte[] Decrypt(ReadOnlySpan<byte> ciphertext) => Decrypt(ciphertext, new OAEPEncoder(HashAlgorithmName.SHA256));

    /// <summary>
    /// Decrypts a ciphertext using a caller-supplied OAEP encoder.
    /// </summary>
    /// <param name="ciphertext">The ciphertext, which must be 2*<see cref="ModulusByteCount"/> bytes.</param>
    /// <param name="encoder">An encoder configured identically to the one used to encrypt.</param>
    /// <returns>The recovered plaintext.</returns>
    /// <exception cref="InvalidOperationException">No private key is held.</exception>
    /// <exception cref="ArgumentException">The ciphertext is the wrong length, too large, or fails OAEP checks.</exception>
    public byte[] Decrypt(ReadOnlySpan<byte> ciphertext, OAEPEncoder encoder) {
        PrivateKey priv = _PrivateKey ?? throw new InvalidOperationException("No private key is held.");
        ArgumentNullException.ThrowIfNull(encoder);

        const string Fail = "Invalid ciphertext.";

        BigInteger p = _Parameters.P, q = _Parameters.Q;
        int len = ModulusByteCount;

        if (ciphertext.Length != 2 * len)
            throw new ArgumentException(Fail, nameof(ciphertext));

        BigInteger c1 = FromBytes(ciphertext[..len]);
        BigInteger c2 = FromBytes(ciphertext[len..]);

        if (c1 < 2 || c1 > p - 2 || c2 < 1 || c2 >= p || BigInteger.ModPow(c1, q, p) != 1)
            throw new ArgumentException(Fail, nameof(ciphertext));

        try {
            BigInteger s = BigInteger.ModPow(c1, priv.X, p);
            BigInteger m = c2 * BigIntegerExtensions.ModInverse(s, p) % p;
            return OaepDecode(encoder, ToFixedBytes(m));
        } catch (Exception) {
            throw new ArgumentException(Fail, nameof(ciphertext));
        }
    }

    #endregion

    #region Signing operations

    /// <summary>
    /// Signs data using ElGamal with SHA-256.
    /// </summary>
    /// <param name="data">The data to sign; it is hashed internally.</param>
    /// <returns>A signature 2*<see cref="ModulusByteCount"/> bytes long (r || s).</returns>
    /// <exception cref="InvalidOperationException">No private key is available.</exception>
    public byte[] Sign(ReadOnlySpan<byte> data) => Sign(data, HashAlgorithmName.SHA256);

    /// <summary>
    /// Signs data using a caller-supplied hash algorithm.
    /// </summary>
    /// <param name="data">The data to sign; it is hashed internally.</param>
    /// <param name="hash">The hashing algorithm to use on the message.</param>
    /// <returns>A signature 2*<see cref="ModulusByteCount"/> bytes long (r || s).</returns>
    /// <exception cref="InvalidOperationException">No private key is held.</exception>
    public byte[] Sign(ReadOnlySpan<byte> data, HashAlgorithmName hash) {
        PrivateKey priv = _PrivateKey ?? throw new InvalidOperationException("No private key is held.");

        BigInteger p = _Parameters.P, q = _Parameters.Q, g = _Parameters.G;
        BigInteger hm = HashToExponent(data, hash, q);

        BigInteger r, s;
        do {
            BigInteger k = RandomBigInteger(1, q);
            r = BigInteger.ModPow(g, k, p);
            BigInteger kInv = BigIntegerExtensions.ModInverse(k, q);
            s = ((kInv * (hm - priv.X * r)) % q + q) % q;
        } while (r % q == 0 || s == 0);

        byte[] sig = new byte[2 * ModulusByteCount];
        ToFixedBytes(r).CopyTo(sig, 0);
        ToFixedBytes(s).CopyTo(sig, ModulusByteCount);
        return sig;
    }

    /// <summary>
    /// Verifies an ElGamal signature using SHA-256.
    /// </summary>
    /// <param name="data">The data that was supposedly signed.</param>
    /// <param name="signature">The signature to check.</param>
    /// <returns><see langword="true"/> if the signature is valid for this key.</returns>
    public bool Verify(ReadOnlySpan<byte> data, ReadOnlySpan<byte> signature) => Verify(data, signature, HashAlgorithmName.SHA256);

    /// <summary>
    /// Verifies an ElGamal signature using a caller-supplied hash function. Malformed input is reported
    /// as <c>false</c> rather than thrown, so callers need only one failure path.
    /// </summary>
    /// <param name="data">The data that was supposedly signed.</param>
    /// <param name="signature">The signature to check.</param>
    /// <param name="hash">The hash algorithm used when signing.</param>
    /// <returns><see langword="true"/> if the signature is valid for this key.</returns>
    public bool Verify(ReadOnlySpan<byte> data, ReadOnlySpan<byte> signature, HashAlgorithmName hash) {
        try {
            int len = ModulusByteCount;
            if (signature.Length != 2 * len) return false;

            BigInteger p = _Parameters.P, q = _Parameters.Q, g = _Parameters.G;
            BigInteger r = FromBytes(signature[..len]);
            BigInteger s = FromBytes(signature[len..]);

            if (r < 1 || r >= p || s < 1 || s >= q) return false;

            BigInteger hm = HashToExponent(data, hash, q);
            BigInteger lhs = BigInteger.ModPow(g, hm, p);
            BigInteger rhs = BigInteger.ModPow(_PublicKey.H, r, p) * BigInteger.ModPow(r, s, p) % p;
            return (lhs == rhs);
        } catch (Exception) {
            return false;
        }
    }

    #endregion

}
